const props = defineProps({
	// 'fid' | 'fpd' | 'fid_cutoff' | 'fpd_cutoff'
	type: { type: String, default: 'fid' },
	name: { type: String, required: true },
})

const router = useRouter()
const route = useRoute()

// Konteks marketing terpilih (m = id_marketing) — kunci detail ke marketing tsb.
