	url: 'juragan.api.portal.fid_fpd.get_fid_fpd_detail',
	method: 'GET',
	auto: false,
	makeParams: () => {
		const p = { type: props.type, name: props.name }
		// Hanya sertakan saat ada konteks marketing — jangan kirim "undefined".
		if (route.query.m) p.id_marketing = route.query.m
		return p
	},
})

const errorMessage = computed(() => {
	if (!detail.error) return ''
	const e = detail.error
	return e?.messages?.[0] || e?.message || 'Gagal memuat detail data.'
})

watch(
	() => [props.type, props.name],
	() => detail.fetch(),
	{ immediate: true }
)

// ===== Collapse per section =====
// Set berisi index section yang sedang DISEMBUNYIKAN. Default: semua section
// terbuka. Direset tiap kali dokumen yang dibuka berganti.
const collapsedSections = ref(new Set())
function isCollapsed(i) {
	return collapsedSections.value.has(i)
}
function toggleSection(i) {
	const next = new Set(collapsedSections.value)
	next.has(i) ? next.delete(i) : next.add(i)
	collapsedSections.value = next
}
watch(
	() => [props.type, props.name],
	() => {
		collapsedSections.value = new Set()
	}
)

// ===== Dialog Input Keterangan =====
const showDialog = ref(false)
const saving = ref(false)
const ketForm = reactive({ keterangan: '', tanggal_janji_bayar: '', foto: null })
let fotoFile = null

function openKeterangan() {
	ketForm.keterangan = ''
	ketForm.tanggal_janji_bayar = ''
	ketForm.foto = null
	fotoFile = null
	showDialog.value = true
}

function onFotoChange(e) {
	fotoFile = e.target.files?.[0] || null
}

// Upload file ke Frappe → kembalikan file_url. Pakai endpoint upload_file standar.
async function uploadFoto(file) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	fd.append('is_private', '0')
	fd.append('folder', 'Home/Attachments')
	const res = await fetch('/api/method/upload_file', {
		method: 'POST',
		headers: { 'X-Frappe-CSRF-Token': window.csrf_token || '' },
		credentials: 'include',
		body: fd,
	})
	if (!res.ok) throw new Error('Gagal mengunggah foto.')
	const data = await res.json()
	return data?.message?.file_url || null
}

const insertResource = createResource({
	url: 'juragan.api.portal.fid_fpd.insert_keterangan',
	method: 'POST',
})

async function submitKeterangan() {
	if (!ketForm.keterangan.trim()) {
		toast.error('Keterangan wajib diisi.')
		return
	}
	if (!ketForm.tanggal_janji_bayar) {
		toast.error('Tanggal Janji Bayar wajib diisi.')
		return
	}
	saving.value = true
	try {
		let fotoUrl = null
		if (showFoto.value && fotoFile) {
			fotoUrl = await uploadFoto(fotoFile)
		}
		const r = await insertResource.submit({
			type: props.type,
			name: props.name,
			keterangan: ketForm.keterangan,
			tanggal_janji_bayar: ketForm.tanggal_janji_bayar,
			foto: fotoUrl,
		})
		toast.success(`Keterangan berhasil disimpan: ${r?.name || ''}`.trim())
		showDialog.value = false
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || 'Gagal menyimpan keterangan.')
	} finally {
		saving.value = false
	}
}

// ===== Helpers =====
const ID_MONTHS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'Mei',
	'Jun',
	'Jul',
	'Agu',
	'Sep',
	'Okt',
	'Nov',
	'Des',
]
function formatDate(d) {
	if (!d) return '-'
	const [y, m, day] = String(d).split(' ')[0].split('-')
	if (!y || !m || !day) return d
	return `${day} ${ID_MONTHS[Number(m) - 1] || m} ${y}`
}
const rupiah = new Intl.NumberFormat('id-ID', {
	style: 'currency',
	currency: 'IDR',
	minimumFractionDigits: 0,
	maximumFractionDigits: 0,
})
function formatValue(f) {
	const v = f.value
	if (v === null || v === undefined || v === '') return '-'
	if (f.fieldtype === 'Currency') {
		const n = Number(v)
		return Number.isFinite(n) ? rupiah.format(n) : v
	}
	if (f.fieldtype === 'Date' || f.fieldtype === 'Datetime') return formatDate(v)
	return v
}
function initials(name) {
	if (!name) return '?'
	return name.trim()[0]?.toUpperCase() || '?'
}

// ===== Cek Tunggakan (mirror tombol desk Data FID/FPD Live) =====
const showTunggakan = ref(false)
const tunggakanRes = createResource({
	url: 'juragan.api.portal.fid_fpd.get_tunggakan',
	method: 'GET',
	auto: false,
	makeParams: () => {
		const p = { type: props.type, name: props.name }
		// Bawa konteks marketing (Pimcab) agar gate-nya sama dengan detail.
		if (route.query.m) p.id_marketing = route.query.m
		return p
	},
})
function openTunggakan() {
	showTunggakan.value = true
	tunggakanRes.fetch() // data live n8n → ambil ulang tiap dibuka
}
const tunggakanError = computed(() => {
	const e = tunggakanRes.error
	if (!e) return ''
	return e?.messages?.[0] || e?.message || 'Gagal mengambil data tunggakan.'
})
// Hanya baris tunggakan (sembunyikan Lunas / Lunas dipercepat / kosong) — sama desk.
const tunggakanRows = computed(() => {
	const rows = tunggakanRes.data?.rincian?.tabel_angsuran
	if (!Array.isArray(rows)) return []
	return rows.filter((row) => {
		const st = String(row.Status || '')
			.trim()
			.toLowerCase()
		return !['lunas', 'lunas (dipercepat)', '-', ''].includes(st)
	})
})
// Info header nasabah (field & urutan sama desk).
const nasabahInfo = computed(() => {
	const n = tunggakanRes.data?.nasabah || {}
	return [
		{ label: 'Nama Nasabah', value: n.nama_nasabah || '-' },
		{ label: 'Nama Kendaraan', value: `${n.merk || ''} ${n.model || ''}`.trim() || '-' },
		{ label: 'Plafond', value: fmtRp(n.pinjaman) },
		{ label: 'No. Polisi', value: n.nopol || '-' },
		{ label: 'Jangka Waktu', value: n.tenor ? `${n.tenor} Bulan` : '-' },
		{
			label: 'Tanggal Pencairan',
			value: n.tanggal_pencairan ? formatDate(n.tanggal_pencairan) : '-',
		},
	]
})
// Ringkasan finansial (semua field desk; Total Hutang ditonjolkan terpisah).
const ringkasan = computed(() => {
	const r = tunggakanRes.data?.rincian || {}
	return [
		{ label: 'Total Denda', value: fmtRp(r.total_denda) },
		{ label: 'Sisa Pokok', value: fmtRp(r.sisa_pokok) },
		{ label: 'Sisa Bunga', value: fmtRp(r.sisa_bunga) },
		{ label: 'Sisa Admin', value: fmtRp(r.sisa_admin) },
		{ label: 'Total Sisa Angsuran', value: fmtRp(r.total_sisa_angsuran) },
		{ label: 'Saldo Tabungan', value: fmtRp(r.saldo_tabungan) },
	]
})
// Format angka → "Rp 1.234.567" (nilai bisa string/number dari n8n).
function fmtRp(v) {
	let n = typeof v === 'string' ? parseFloat(v.replace(/,/g, '')) : Number(v)
	if (!Number.isFinite(n)) n = 0
	return 'Rp ' + new Intl.NumberFormat('id-ID', { maximumFractionDigits: 0 }).format(n)
}
function nowStr() {
	const d = new Date()
	const p = (x) => String(x).padStart(2, '0')
	return `${p(d.getDate())}-${p(d.getMonth() + 1)}-${d.getFullYear()} ${p(d.getHours())}:${p(
		d.getMinutes()
	)}`
}

function goBack() {
	router.push({ name: cfg.value.listRoute, query: marketingQuery.value })
}
</script>
